{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Shared Game World Faction",
  "type": "object",
  "additionalProperties": false,
  "required": ["status", "summary", "visibility", "goals", "methods", "assets", "agenda"],
  "properties": {
    "status": { "enum": ["draft", "active", "archived"] },
    "summary": { "type": "string", "minLength": 1, "maxLength": 1000 },
    "visibility": { "enum": ["public", "party", "gm"] },
    "goals": {
      "type": "array",
      "minItems": 1,
      "maxItems": 5,
      "uniqueItems": true,
      "items": { "type": "string", "minLength": 1, "maxLength": 500 }
    },
    "methods": {
      "type": "array",
      "minItems": 1,
      "maxItems": 5,
      "uniqueItems": true,
      "items": { "type": "string", "minLength": 1, "maxLength": 500 }
    },
    "assets": {
      "type": "array",
      "minItems": 0,
      "maxItems": 10,
      "uniqueItems": true,
      "items": { "type": "string", "minLength": 1, "maxLength": 500 }
    },
    "agenda": {
      "type": "object",
      "additionalProperties": false,
      "required": ["state", "summary"],
      "properties": {
        "state": { "enum": ["ready", "advanced"] },
        "summary": { "type": "string", "minLength": 1, "maxLength": 1000 }
      }
    }
  },
  "$comment": "Governed by procedure.game.core.world.faction. This component contains descriptive assets only; entity references, members, controls, alliances, and opposition are relationships."
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Shared Game World Secret",
  "type": "object",
  "additionalProperties": false,
  "required": ["status", "summary", "provenance", "visibility"],
  "properties": {
    "status": { "enum": ["active", "archived"] },
    "summary": { "type": "string", "minLength": 1, "maxLength": 1000 },
    "provenance": { "type": "string", "minLength": 1, "maxLength": 500 },
    "visibility": { "const": "gm" }
  },
  "$comment": "Governed by procedure.game.core.world.knowledge. Visibility is descriptive metadata, not access control."
}
